import{_ as e,o as t,c as s,a0 as r}from"./chunks/framework.l456sJqm.js";const i="/mtbbs/images/InsertLabel/Pasted%20image%2020260104104050.png",n="/mtbbs/images/InsertLabel/Pasted%20image%2020260104105047.png",o="/mtbbs/images/InsertLabel/Pasted%20image%2020260104105229.png",l="/mtbbs/images/InsertLabel/Pasted%20image%2020260104105246.png",h="/mtbbs/images/InsertLabel/Pasted%20image%2020260104105732.png",m="/mtbbs/images/InsertLabel/Pasted%20image%2020260104111125.png",c="/mtbbs/images/InsertLabel/Pasted%20image%2020260104111530.png",d="/mtbbs/images/InsertLabel/Pasted%20image%2020260104111725.png",p="/mtbbs/images/InsertLabel/Pasted%20image%2020260104112713.png",b="/mtbbs/images/InsertLabel/Pasted%20image%2020260104112108.png",g="/mtbbs/images/InsertLabel/Pasted%20image%2020260104110859.png",u="/mtbbs/images/InsertLabel/Pasted%20image%2020260104113223.png",P="/mtbbs/images/InsertLabel/Pasted%20image%2020260104112845.png",S=JSON.parse('{"title":"发帖辅助工具","description":"","frontmatter":{},"headers":[],"relativePath":"scripts/InsertLabel.md","filePath":"scripts/InsertLabel.md","lastUpdated":1783220091000}'),_={name:"scripts/InsertLabel.md"};function q(f,a,k,x,I,L){return t(),s("div",null,[...a[0]||(a[0]=[r('<h1 id="发帖辅助工具" tabindex="-1">发帖辅助工具 <a class="header-anchor" href="#发帖辅助工具" aria-label="Permalink to &quot;发帖辅助工具&quot;">​</a></h1><h1 id="帖子" tabindex="-1">帖子 <a class="header-anchor" href="#帖子" aria-label="Permalink to &quot;帖子&quot;">​</a></h1><p><a href="https://bbs.binmt.cc/thread-154052-1-1.html" target="_blank" rel="noreferrer">【论坛脚本】论坛自用发帖工具js（InsertLabel_2.0.js）</a></p><h1 id="页面" tabindex="-1">页面 <a class="header-anchor" href="#页面" aria-label="Permalink to &quot;页面&quot;">​</a></h1><p><img src="'+i+'" alt="attachments/Pasted image 20260104104050.png"> 脚本会自动寻找网页中textarea元素，在其之后添加一横排按钮。</p><h1 id="功能" tabindex="-1">功能 <a class="header-anchor" href="#功能" aria-label="Permalink to &quot;功能&quot;">​</a></h1><h2 id="便携插入标签" tabindex="-1">便携插入标签 <a class="header-anchor" href="#便携插入标签" aria-label="Permalink to &quot;便携插入标签&quot;">​</a></h2><p>建议先阅读常见标签：<a href="https://bbs.binmt.cc/thread-161119-1-1.html" target="_blank" rel="noreferrer">【论坛教程】mt论坛语法总汇（bbcode） - MT论坛</a></p><h3 id="使用方法" tabindex="-1">使用方法 <a class="header-anchor" href="#使用方法" aria-label="Permalink to &quot;使用方法&quot;">​</a></h3><p>选中一段文字，点击S，则会使用S标签将选中的内容包裹 <img src="'+n+'" alt="attachments/Pasted image 20260104105047.png"> 或者未选中时，手动输入内容 <img src="'+o+'" alt="attachments/Pasted image 20260104105229.png"><img src="'+l+'" alt="attachments/Pasted image 20260104105246.png"> 注意url插入时有两种情况，如果只是插入链接，只输入第一个文本框即可。如果想显示文字，则上输入文字，下输入链接。</p><h2 id="插图" tabindex="-1">插图 <a class="header-anchor" href="#插图" aria-label="Permalink to &quot;插图&quot;">​</a></h2><p><img src="'+h+'" alt="attachments/Pasted image 20260104105732.png"> 本质上只是优化页面显示，如果你的图片不符合论坛要求，或遇见论坛bug，仍无法上传使用。</p><h3 id="简要介绍" tabindex="-1">简要介绍 <a class="header-anchor" href="#简要介绍" aria-label="Permalink to &quot;简要介绍&quot;">​</a></h3><p>左侧为缩略图，右侧显示对应大图，如果觉得还不够大，点击大图右上角<strong>全屏</strong>，将在新标签显示此图片。 确认后点击插入，将在光标处插入对应标签，例如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[attachimg]349346[/attachimg]</span></span></code></pre></div><h2 id="预览" tabindex="-1">预览 <a class="header-anchor" href="#预览" aria-label="Permalink to &quot;预览&quot;">​</a></h2><p>有一点小bug，可以预览发帖后效果 <img src="'+m+'" alt="attachments/Pasted image 20260104111125.png"></p><h2 id="常用语" tabindex="-1">常用语 <a class="header-anchor" href="#常用语" aria-label="Permalink to &quot;常用语&quot;">​</a></h2><p><img src="'+c+'" alt="attachments/Pasted image 20260104111530.png"> 备注用于列表显示，使用场景：你有一串非常好看的<strong>感谢分享</strong>代码，将其添加至常用语中，下次快捷插入</p><h2 id="彩虹字体" tabindex="-1">彩虹字体 <a class="header-anchor" href="#彩虹字体" aria-label="Permalink to &quot;彩虹字体&quot;">​</a></h2><p><img src="'+d+'" alt="attachments/Pasted image 20260104111725.png"> 填写文字，拖动生成。</p><h3 id="使用技巧" tabindex="-1">使用技巧 <a class="header-anchor" href="#使用技巧" aria-label="Permalink to &quot;使用技巧&quot;">​</a></h3><p>选择文字，点击此功能生成。或者未选择文字，点击编辑框，添加文字，再生成。</p><h2 id="移除标签" tabindex="-1">移除标签 <a class="header-anchor" href="#移除标签" aria-label="Permalink to &quot;移除标签&quot;">​</a></h2><h3 id="使用示例" tabindex="-1">使用示例 <a class="header-anchor" href="#使用示例" aria-label="Permalink to &quot;使用示例&quot;">​</a></h3><p>输入color，代码将自动删除</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[color]、[/color]、[color=xxx]</span></span></code></pre></div><p>标签，相当于反彩虹字体。</p><h2 id="更多" tabindex="-1">更多 <a class="header-anchor" href="#更多" aria-label="Permalink to &quot;更多&quot;">​</a></h2><p><img src="'+p+'" alt="attachments/Pasted image 20260104112713.png"> 显示代码中隐藏的标签 <img src="'+b+'" alt="attachments/Pasted image 20260104112108.png"> 每个人常用的功能、标签不一样，将自己不常用的功能隐藏，在更多中显示。</p><h2 id="小工具" tabindex="-1">小工具 <a class="header-anchor" href="#小工具" aria-label="Permalink to &quot;小工具&quot;">​</a></h2><h3 id="撤销、恢复" tabindex="-1">撤销、恢复 <a class="header-anchor" href="#撤销、恢复" aria-label="Permalink to &quot;撤销、恢复&quot;">​</a></h3><p>不解释</p><h3 id="选择" tabindex="-1">选择 <a class="header-anchor" href="#选择" aria-label="Permalink to &quot;选择&quot;">​</a></h3><p>可以选择中括号包裹的内容，例如 <img src="'+g+'" alt="attachments/Pasted image 20260104110859.png"> 光标在数字之间，点击选择将选中整个标签，方便后续操作。</p><h3 id="阻止离开" tabindex="-1">阻止离开 <a class="header-anchor" href="#阻止离开" aria-label="Permalink to &quot;阻止离开&quot;">​</a></h3><p>如果担心编辑中因操作失误，离开了网页，导致心血白费，可阻止离开。 <img src="'+u+'" alt="attachments/Pasted image 20260104113223.png"> 之后如果网页触发刷新、跳转页面等事件，将提示对话框，点击<strong>取消</strong>阻止离开。</p><h3 id="帖子缓存" tabindex="-1">帖子缓存 <a class="header-anchor" href="#帖子缓存" aria-label="Permalink to &quot;帖子缓存&quot;">​</a></h3><p><img src="'+P+'" alt="attachments/Pasted image 20260104112845.png"> 默认每30秒记录一次内容，一定程度上离开后可找回部分丢失进度，点击确定插入。</p>',39)])])}const T=e(_,[["render",q]]);export{S as __pageData,T as default};
